package dsl

import "github.com/DonaldMurillo/gofastr/core/i18n"

// The refusals a DSL query, ?filter= or ?sort= parse returns.
var (
	reasonInputTooLong           = i18n.Define("dsl.input_too_long", "dsl: input exceeds {{max}} bytes")
	reasonEmptyQuery             = i18n.Define("dsl.empty_query", "dsl: query is empty")
	reasonEntityRequired         = i18n.Define("dsl.entity_required", "dsl: entity is required")
	reasonInvalidEntity          = i18n.Define("dsl.invalid_entity", "dsl: invalid entity name {{name}}")
	reasonInvalidFilterField     = i18n.Define("dsl.invalid_filter_field", "dsl: invalid filter field name {{name}}")
	reasonInvalidInclude         = i18n.Define("dsl.invalid_include", "dsl: invalid include name {{name}}")
	reasonInvalidOrderField      = i18n.Define("dsl.invalid_order_field", "dsl: invalid order field name {{name}}")
	reasonLimitNotPositive       = i18n.Define("dsl.limit_not_positive", "dsl: limit must be a positive integer")
	reasonLimitOverMax           = i18n.Define("dsl.limit_over_max", "dsl: limit {{limit}} exceeds max {{max}}")
	reasonUnknownCall            = i18n.Define("dsl.unknown_call", "dsl: unknown call {{name}}")
	reasonRelationNotFound       = i18n.Define("dsl.relation_not_found", "dsl: relation {{name}} not found on {{entity}}")
	reasonFieldNotFound          = i18n.Define("dsl.field_not_found", "dsl: field {{field}} not found on {{entity}}")
	reasonFieldNotFilterable     = i18n.Define("dsl.field_not_filterable", "dsl: field {{field}} on {{entity}} cannot be filtered")
	reasonFieldNotSortable       = i18n.Define("dsl.field_not_sortable", "dsl: field {{field}} on {{entity}} cannot be sorted on")
	reasonAfterComposite         = i18n.Define("dsl.after_composite", "dsl: after() is unsupported on {{entity}} (composite cursor); use the HTTP cursor API")
	reasonAfterFieldNotFound     = i18n.Define("dsl.after_field_not_found", "dsl: after() cursor field {{field}} not found on {{entity}}")
	reasonAfterFieldNotQueryable = i18n.Define("dsl.after_field_not_queryable", "dsl: after() cursor field {{field}} on {{entity}} cannot be queried")
	reasonAfterNotUnique         = i18n.Define("dsl.after_not_unique", "dsl: after() cursor field {{field}} on {{entity}} is not unique, so rows tied on it would be skipped; mark the field Unique, cursor on the key, or use the HTTP cursor API")
	reasonExpectedCall           = i18n.Define("dsl.expected_call", "dsl: expected call in {{input}}")
	reasonUnclosedCall           = i18n.Define("dsl.unclosed_call", "dsl: unclosed call {{name}}")
	reasonInvalidFilter          = i18n.Define("dsl.invalid_filter", "dsl: invalid filter {{input}}")
	reasonInvalidOrder           = i18n.Define("dsl.invalid_order", "dsl: invalid order {{input}}")
	reasonInvalidDirection       = i18n.Define("dsl.invalid_direction", "dsl: invalid order direction {{dir}}")
	reasonInNeedsValue           = i18n.Define("dsl.in_needs_value", "dsl: in operator requires at least one value")
	reasonUnsupportedOperator    = i18n.Define("dsl.unsupported_operator", "dsl: unsupported operator {{op}}")

	reasonFilterTooLong    = i18n.Define("dsl.filter_too_long", "filter: input exceeds {{max}} bytes")
	reasonSortTooLong      = i18n.Define("dsl.sort_too_long", "sort: input exceeds {{max}} bytes")
	reasonSortTooMany      = i18n.Define("dsl.sort_too_many", "sort: too many sort keys: {{count}} (max {{max}})")
	reasonSortEmptyKey     = i18n.Define("dsl.sort_empty_key", "sort: empty sort key")
	reasonSortBadTerm      = i18n.Define("dsl.sort_bad_term", "sort: {{term}} is not `field [ASC|DESC]`")
	reasonSortBadFieldName = i18n.Define("dsl.sort_bad_field_name", "sort: invalid field name at {{name}}")
	reasonSortBadDirection = i18n.Define("dsl.sort_bad_direction", "sort: invalid direction {{dir}} (want ASC or DESC)")
	reasonNotSortable      = i18n.Define("dsl.not_sortable", "field {{field}} cannot be sorted on")
	reasonInvalidSortField = i18n.Define("dsl.invalid_sort_field", "invalid sort field {{field}}")

	// The ?filter= expression parser names where it stopped.
	reasonUnexpectedInput    = i18n.Define("dsl.unexpected_input", "filter: offset {{offset}}: unexpected input after expression (near {{near}})")
	reasonExpectedParen      = i18n.Define("dsl.expected_paren", "filter: offset {{offset}}: expected ) (near {{near}})")
	reasonExpectedFieldName  = i18n.Define("dsl.expected_field_name", "filter: offset {{offset}}: expected field name (near {{near}})")
	reasonExpectedValueWord  = i18n.Define("dsl.expected_value_word", "filter: offset {{offset}}: expected value (near {{near}})")
	reasonExpectedOperator   = i18n.Define("dsl.expected_operator", "filter: offset {{offset}}: expected an operator (=, !=, <, >, <=, >=, contains, in) (near {{near}})")
	reasonExpectedValue      = i18n.Define("dsl.expected_value", "filter: offset {{offset}}: expected a value (near {{near}})")
	reasonBareWord           = i18n.Define("dsl.bare_word", "filter: offset {{offset}}: bare words must be quoted; only numbers, true and false may go unquoted (near {{near}})")
	reasonUnterminatedEscape = i18n.Define("dsl.unterminated_escape", "filter: offset {{offset}}: unterminated escape in string (near {{near}})")
	reasonBadEscape          = i18n.Define("dsl.bad_escape", `filter: offset {{offset}}: only \" and \\ may be escaped (near {{near}})`)
	reasonUnterminatedString = i18n.Define("dsl.unterminated_string", "filter: offset {{offset}}: unterminated string (near {{near}})")
	reasonExpectedNumber     = i18n.Define("dsl.expected_number", "filter: offset {{offset}}: expected a number (near {{near}})")
	reasonExpectedFraction   = i18n.Define("dsl.expected_fraction", "filter: offset {{offset}}: expected digits after the decimal point (near {{near}})")
	reasonExpectedExponent   = i18n.Define("dsl.expected_exponent", "filter: offset {{offset}}: expected digits in the exponent (near {{near}})")
	reasonInNeedsList        = i18n.Define("dsl.in_needs_list", "filter: offset {{offset}}: in requires a bracketed list like [\"a\", \"b\"] (near {{near}})")
	reasonUnterminatedList   = i18n.Define("dsl.unterminated_list", "filter: offset {{offset}}: unterminated list, expected , or ] (near {{near}})")
	reasonExpectedListSep    = i18n.Define("dsl.expected_list_sep", "filter: offset {{offset}}: expected , or ] in list (near {{near}})")
)
